"""Explain RCU reuse, record lifetime and length boundaries simply."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1901': ('돌려받은 공책도 누군가 마지막 페이지를 읽고 있다면 바로 지우면 안 돼요. 재사용할 기록도 예전 읽기가 끝날 시간을 확인해요.', '참조 수 0과 RCU 대기 완료가 다른 조건임을 이해합니다.', '재사용 줄 A→B에서 A의 기다림이 끝나지 않았으면 아무것도 꺼내지 않는다고 적으세요. 끝났으면 A를 꺼내고 B를 남겨요.', ['free_stacks는 다시 쓸 기록들을 연결해 둔 목록이에요. freelist는 이런 재사용 목록을 뜻해요. 기록을 돌려놓을 때 뒤에 붙이고 꺼낼 때 앞부터 봐요. 먼저 들어온 것을 먼저 살피는 순서를 FIFO라고 불러요.', '참조 수는 기록을 계속 보관해 달라고 확보한 사용 권리의 수예요. 이 수가 0이 되면 정상적인 사용 권리는 끝났지만, 다른 실행이 검색 목록을 따라오던 도중 그 기록을 아직 보고 있을 수 있어요. 0이라는 숫자만으로 모든 읽기가 끝났다고 판단할 수 없어요.', 'RCU는 읽는 쪽과 바꾸는 쪽이 함께 일할 때 자료의 수명을 관리하는 방법이에요. 여기서는 예전에 시작한 관련 읽기가 끝날 수 있도록 유예 기간을 확인해요. rcu_state는 그 완료 여부를 물어볼 때 쓰는 상태표이고, 원문에서는 cookie라고도 불러요. 과자나 웹 로그인 정보라는 뜻이 아니에요.', 'depot_pop_free는 목록이 비었으면 NULL을 돌려줘요. NULL은 꺼낸 기록이 없다는 표시예요. 목록이 있으면 맨 앞 기록 하나의 상태만 poll_state_synchronize_rcu로 확인해요. 아직 완료되지 않았으면 역시 NULL을 돌려주며 뒤 항목을 계속 찾지는 않아요.', '앞쪽에 오래전에 돌려놓은 기록이 오도록 유지하므로 먼저 재사용할 수 있을 가능성도 앞쪽이 높아요. 그래서 목록 전체를 매번 훑지 않아요. 이 순서가 지켜진다는 약속을 불변식이라고 해요. 단순히 운 좋게 앞에 놓였다는 뜻이 아니에요.', '완료된 맨 앞 기록은 list_del로 재사용 목록에서 빼고 목록 개수 통계를 1 줄인 뒤 반환해요. 이 과정은 pool_lock 잠금 안에서 수행해요. 종이에서 완료 표시를 바꾸는 연습은 분기를 이해하는 방법이며 실제 여러 CPU의 RCU 실행을 재현하지는 않아요.'], [('재사용 목록 맨 앞 기록 A의 RCU 유예 기간이 아직 끝나지 않았어요. 이 함수는 어떻게 하나요?', ['뒤의 기록을 모두 찾아봐요', 'NULL을 돌려주고 이번에는 꺼내지 않아요'], '정답은 두 번째예요. 코드는 맨 앞 기록 하나만 확인해요. 재사용 후보가 목록에 있다는 것과 지금 안전하게 꺼낼 수 있다는 것은 달라요.'), ('참조 수가 0이 되면 기록을 바로 새 내용으로 덮어써도 언제나 안전한가요?', ['아니요. 예전 읽기가 끝났는지 RCU 상태도 확인해야 해요', '네. 참조 수 0이면 어떤 읽기도 남아 있을 수 없어요'], '정답은 첫 번째예요. 검색 중이던 실행이 기록을 아직 볼 수 있어요. 사용 권리의 수와 예전 읽기의 종료를 서로 다른 조건으로 확인해요.')]), 'os1902': ('기록을 계속 보관하는 방식과 사용자가 모두 돌려주면 다시 쓰는 방식이 있어요. 새 기록을 만들 때 어느 방식인지부터 정해요.', 'GET 기록의 시작 참조 수와 초기화 추적의 의미를 이해합니다.', '새 GET 기록의 사용 권리를 1로 적으세요. 저장한 호출 위치 A·B·C는 초기화 표시 뒤에도 A·B·C라고 적으세요.', ['depot_alloc_stack은 함수 호출 경로를 담을 새 기록을 준비해요. 항목 수가 0이면 실패하고, 설정된 최대 개수보다 많으면 저장 개수를 줄여요. hash에는 검색에 쓸 요약 숫자, size에는 저장 항목 수, entries에는 실제 호출 위치들을 담아요.', 'GET 옵션을 쓰면 사용이 끝난 기록을 다시 쓸 수 있어요. 먼저 재사용 목록에서 안전한 기록을 얻으려 하고, 얻지 못하면 pool이라는 메모리 묶음에서 공간을 찾아요. 이때 공간 크기는 나중의 더 긴 기록도 담도록 최대 항목 수에 맞춰요.', '새 GET 기록의 count는 1로 시작해요. 새로 저장한 쪽이 기록을 보관해 달라는 권리 하나를 얻었기 때문이에요. 같은 기록을 GET으로 다시 찾으면 그 권리를 늘리고, 더 필요 없을 때 stack_depot_put으로 하나씩 돌려주는 약속이에요. 사용자가 누구인지 이름을 세는 것이 아니라 얻고 돌려주는 권리를 세어요.', 'GET을 쓰지 않는 새 기록은 계속 보관할 기록으로 취급해요. 필요한 항목 수에 맞춰 공간을 얻고 count에 REFCOUNT_SATURATED라는 특별한 값을 넣어요. 이 값은 보통의 사용자 수가 아니에요. 이런 기록을 나중에 put으로 반환하는 사용법과 섞어서는 안 돼요.', 'memcpy는 호출 위치 배열의 내용을 실제 기록 공간에 복사해요. 그 뒤 kmsan_unpoison_memory는 KMSAN이라는 미초기화 메모리 검사 도구에 이 기록이 초기화된 상태라고 알려요. 초기화란 사용할 값을 준비하는 일이에요. unpoison은 준비 여부를 추적하는 표시를 바꾸며 이미 복사한 호출 위치를 0으로 지우지 않아요.', '예를 들어 entries에 A·B·C라는 세 위치를 복사했다면 초기화 표시를 맞춘 뒤에도 내용은 A·B·C예요. 이 구별이 없으면 검사 도구에 알리는 동작을 실제 데이터 지우기로 오해할 수 있어요. 함수는 참조 기록과 계속 보관할 기록의 통계도 따로 늘려요.'], [('GET 옵션으로 새 기록을 만들었어요. 처음 참조 수 count는 얼마인가요?', ['0이에요', '1이에요'], '정답은 두 번째예요. 저장한 쪽이 보관 권리 하나를 얻었으므로 1에서 시작해요. 0은 사용 권리가 끝난 상태와 연결되므로 새 GET 기록의 시작값과 달라요.'), ('호출 위치들을 복사한 뒤 kmsan_unpoison_memory를 부르는 이유는 무엇인가요?', ['검사 도구에 기록이 초기화됐다고 알리려고요', '복사한 호출 위치를 전부 0으로 지우려고요'], '정답은 첫 번째예요. 데이터 복사는 memcpy가 해요. 그 뒤 unpoison은 데이터의 준비 상태를 추적하는 표시를 맞춰 잘못된 미초기화 보고를 막으려는 동작이에요.')]), 'os1903': ('열 글자를 보고 같은 문장인지 찾은 뒤, 저장할 때만 여덟 글자로 자르면 다음 검색에서 길이가 달라져요. 줄이는 작업을 언제 하느냐가 중요해요.', '검색 단계의 길이와 저장 단계의 길이 제한을 구분합니다.', '필터 뒤 입력 10개 → 검색 길이 10개 → 최대 8개로 저장을 그리세요. 같은 입력을 다시 찾을 때 10과 저장 길이 8을 비교하세요.', ['frame은 호출 경로에 들어 있는 위치 한 항목이에요. truncation은 너무 긴 입력의 뒷부분을 잘라 줄이는 일이에요. dedup은 같은 내용을 한 기록으로 합쳐 중복 저장을 줄이는 일이에요. 두 동작을 한다고 해서 언제나 같은 결과로 합쳐지는 것은 아니에요.', 'stack_depot_save_flags는 먼저 인터럽트 경로 필터를 적용해요. 인터럽트는 실행 중 긴급한 일을 처리하러 들어가는 흐름이에요. 여기서는 그 필터를 거친 뒤에도 입력이 10개 남았고, 저장할 최대 개수는 8개인 상황을 가정해요. 8은 계산 예시이며 모든 설정의 최대값은 아니에요.', '저장 함수는 이 10개를 바탕으로 hash라는 검색용 요약 숫자를 만들고 기존 기록을 찾아요. find_stack은 요약 숫자뿐 아니라 항목 수도 같은지 확인해요. 같은 요약 숫자가 나왔다고 내용까지 같다고 확정하지 않기 때문이에요.', '기존 기록을 찾지 못해 depot_alloc_stack으로 가면 그 안에서 개수를 최대 8개로 줄여요. 저장된 size는 8이고 호출 위치도 앞의 8개만 복사해요. 앞에서 계산한 hash는 전달받아 저장하지만, 이 함수가 검색 단계의 길이를 거슬러 올라가 8로 바꾸지는 않아요.', '같은 10개 입력을 다시 넣고 필터 결과도 같다고 해 봐요. 검색은 또 길이 10으로 하지만 먼저 저장한 기록의 size는 8이에요. 10과 8이 다르므로 그 기록을 같은 후보로 받아들이지 않아요. 필요한 공간을 얻는 데 성공하면 별도 기록이 생길 수 있어요.', '따라서 항상 앞의 8개만 먼저 요약해서 같은 번호로 합친다고 설명하면 이 코드 순서와 맞지 않아요. 실제 사용 결과를 판단할 때는 호출한 쪽의 입력 길이, 필터 결과, 메모리 확보 성공 여부도 봐야 해요. 여기서는 정한 10개·8개 조건으로 순서를 따라가는 연습을 해요.'], [('필터 뒤 입력은 10개이고 저장 최대값은 8개예요. 새 기록에 저장하는 size는 얼마인가요?', ['제한 없이 10개예요', '최대값에 맞춘 8개예요'], '정답은 두 번째예요. depot_alloc_stack 안에서 저장 개수를 줄여요. 앞의 검색 단계에 10개를 썼다는 사실과 최종 저장 길이는 구분해야 해요.'), ('이 조건에서 같은 10개 입력을 다시 넣으면 반드시 앞 기록과 같은 번호로 합쳐지나요?', ['아니요. 검색 길이 10과 저장 길이 8이 달라 그 기록과 맞지 않아요', '네. 검색 전에 항상 앞의 8개로 먼저 줄여요'], '정답은 첫 번째예요. 길이 제한은 기존 기록을 찾은 뒤 새로 할당하는 함수 안에 있어요. 저장할 때 잘랐다는 사실만으로 이전 검색도 잘린 길이를 썼다고 생각하면 안 돼요.')]), 'os1904': ('보관함 번호표를 읽으면 어느 상자의 어느 칸인지 알 수 있어요. 하지만 숫자를 아무렇게나 만든 쪽지가 진짜 번호표가 되는 것은 아니에요.', 'handle 위치 복원과 검사 범위, 기록 수명 조건을 이해합니다.', '번호표의 pool 부분이 3, offset 부분이 2이면 실제 pool 번호 2, 안쪽 위치 32바이트라고 계산하세요.', ['handle은 저장된 기록을 찾는 식별 번호예요. depot_fetch_stack은 번호를 풀어 기록의 주소를 찾는 내부 함수예요. 주소는 실제 기록이 있는 메모리 위치를 뜻해요. 이 함수는 그 기록의 내용을 새 공간에 복사하는 함수가 아니에요.', 'pool_index_plus_1에는 실제 메모리 묶음 번호에 1을 더해 저장했으므로 읽을 때 1을 빼요. offset에는 16바이트 단위 위치를 저장했으므로 왼쪽으로 4칸 이동해 16을 곱해요. pool 부분 3과 offset 부분 2라면 실제 번호 2와 위치 32바이트가 돼요.', '먼저 현재 등록된 pool 개수를 읽고, 복원한 번호가 그 범위 안인지 확인해요. 예를 들어 개수가 3이면 번호 0·1·2를 쓸 수 있고 번호 3은 범위 밖이에요. 범위를 벗어나면 경고를 내고 NULL로 실패를 알리는 경로로 가요.', '그다음 해당 pool 주소가 있는지 확인하고 pool 시작 주소에 offset을 더해 기록 주소를 구해요. 그 기록의 참조 수가 0이면 유효한 기록으로 돌려주지 않아요. 참조 수 0 경고 뒤에는 NULL을 반환하는 코드가 있어요. 경고 설정에 따라 실행 자체가 멈출 수 있는 경우와 정상적으로 반환하는 경로는 구별해요.', '이 검사만으로 아무 숫자나 안전한 handle이라고 보장하지는 않아요. offset이 진짜 기록의 시작인지 모두 대조하는 검사는 없고, count를 읽을 때는 이미 계산한 주소에 접근해요. 저장 함수가 준 유효한 번호를 그 기록의 사용 권리가 유지되는 동안 써야 해요.', '이 함수는 참조 수를 새로 늘리지 않아요. 번호를 읽어 주소를 얻었다고 보관 권리가 하나 더 생기는 것은 아니에요. put으로 마지막 권리를 돌려준 옛 번호를 계속 쓰는 연습은 하지 말고, 종이에서 번호 계산과 실패 조건을 따로 확인하세요.'], [('기록의 참조 수가 0인데 handle 숫자가 남아 있어요. 이 내부 함수가 그 기록을 유효하다고 반환하나요?', ['네. 번호만 있으면 언제나 유효해요', '아니요. 경고 뒤 NULL을 반환하는 경로로 가요'], '정답은 두 번째예요. 번호표가 남았다는 것과 기록의 사용 권리가 유지된다는 것은 달라요. 마지막 권리를 돌려준 뒤 옛 번호를 계속 사용하면 안 돼요.'), ('pool 번호가 범위 안이면 아무 offset이나 안전한 기록 시작 위치라고 확정할 수 있나요?', ['아니요. 실제 기록의 시작과 사용 수명까지 보장하는 검사는 아니에요', '네. 이 함수가 모든 임의 숫자를 안전하게 검증해요'], '정답은 첫 번째예요. 상자 번호가 맞아도 가리키는 칸이 실제 기록의 시작이라는 보장은 없어요. 저장 함수에서 받은 유효한 handle을 사용 약속에 맞게 써야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_471.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
